      "pattern": "storage_failure",
      "description": "Memories are truncated during ingestion (e.g., 'Lost my', 'Just got back from a', 'I s', 'I'm s'), losing critical downstream context including temporal markers and full predicates. This prevents accurate extraction of date information even when the original session_text contains it.",
      "frequency": 4,
      "evidence": ["All 4 cases show memory snippets ending mid-sentence with ellipsis-like truncation; ground truth dates exist in full session_text but are absent from stored memories."]
    },
    {
      "pattern": "retrieval_failure",
      "description": "Retrieval returns only the first (truncated) memory chunk, despite the presence of later, more informative segments in the session_text that contain explicit or inferable temporal information (e.g., 'yesterday', 'last week', 'the week before March 27, 2023'). The system fails to retrieve or prioritize contextually relevant utterances containing time references.",
      "frequency": 4,
      "evidence": ["In every case, retrieved_memories contain only the initial truncated snippet — never the later parts where temporal cues appear (e.g., 'yesterday' in Jon's reply is cut off; 'last week' in Andrew's statement is missing from retrieval)."]
    },
    {
      "pattern": "memory_quality_failure",
      "description": "Stored memories lack semantic coherence and temporal anchoring: they are raw, unstructured text fragments without normalization (e.g., no date parsing, no entity linking, no temporal tagging), making them unsuitable for precise QA. Critical temporal modifiers ('yesterday', 'last week') are either omitted or severed from their referents.",
      "frequency": 4,
      "evidence": ["All stored memories omit or break temporal expressions: 'Lost my job as a banker yesterday' → stored as 'Lost my'; 'Just got back from a family road trip yesterday' → stored as 'Just got back from a'; 'started a new job as a Financial Analyst last week' → stored as 'I s'. No normalization or annotation of time expressions occurs."]
    }
  ],
  "recommendations": [
    {
      "skill_change": "Implement sentence-aware, boundary-respecting memory segmentation",
      "concrete_action": "Replace fixed-length or character-based chunking with NLP-driven sentence splitting (e.g., using spaCy or Punkt tokenizer) followed by whole-sentence or clause-level storage — ensuring temporal phrases like 'yesterday' remain attached to their verbs and subjects."
    },
    {
      "skill_change": "Introduce temporal-aware retrieval augmentation",
      "concrete_action": "Augment retrieval with temporal query expansion: rewrite questions containing 'when' to include synonyms ('date', 'on what day', 'in what year') and inject temporal anchors (e.g., 'yesterday', 'last week', 'March 2023') as dense embedding keywords; rerank retrieved chunks by temporal phrase density and proximity to target entities."
    },
    {
      "skill_change": "Add structured memory annotation at ingestion time",
      "concrete_action": "During memory storage, run lightweight temporal NER (e.g., using Duckling or rule-based pattern matching) to extract and store normalized time expressions (e.g., {'temporal_span': 'yesterday', 'normalized_date': '2023-01-19'}) alongside each memory, enabling direct lookup or inference during QA."
    }
  ]
}

